Item.method_code:
const getCacheData = (node, preferenceOptions) => {
	const key = aras.MetadataCache.CreateCacheKey(...preferenceOptions);
	const item = aras.IomFactory.CreateCacheableContainer(node, node);
	return { key, item };
};

const updateCache = (preferenceNode) => {
	const { id } = preferenceNode;
	const relshipNode = preferenceNode.selectSingleNode('/*/Relationships');
	if (relshipNode) {
		for (const preferenceItem of relshipNode.children) {
			const preferenceITName = preferenceItem.getAttribute('type');
			const { preferenceCategoryGuid } = aras;
			const { key, item } = getCacheData(preferenceItem, [
				'Preference',
				preferenceITName,
				preferenceCategoryGuid
			]);
			aras.MetadataCache.SetItem(key, item);
		}

		preferenceNode.removeChild(relshipNode);
	}

	const { key, item } = getCacheData(preferenceNode, ['Preference', id]);
	aras.MetadataCache.SetItem(key, item);
	window.aras.getMainWindow().store.boundActionCreators.setVariable('PreferenceMainItemID', id);
};

(async () => {
	const result = await aras.soapSendAsync(
		`<Item type="Method" action="ResetUserPreference"/>`
	);
	const resultBody = result.getResultsBody();
	const { documentElement: preferenceNode } =
		ArasModules.xml.parseString(resultBody);

	const initialGlobalPreferences = {};
	const globalXmlPreferences = preferenceNode.selectSingleNode('Relationships/Item[@type="Core_GlobalLayout"]');
	if (globalXmlPreferences) {
		const jsonPreferences = ArasModules.xmlToJson(globalXmlPreferences);
		const count = Number(jsonPreferences['recent_tabs_count']);
		if (!Number.isNaN(count)) {
			initialGlobalPreferences['recent_tabs_count'] = count;
		}
		if (jsonPreferences['recent_tabs']) {
			initialGlobalPreferences['recent_tabs'] = jsonPreferences['recent_tabs'];
		}
		if (jsonPreferences['discussion_state']) {
			initialGlobalPreferences['discussion_state'] = jsonPreferences['discussion_state'];
		}
	}

	aras.resetUserPreferences();
	updateCache(preferenceNode);

	const notify = aras.getNotifyByContext(window);
	const successMessage = aras.getResource('', 'common.references_were_reset');
	notify(successMessage, { type: 'success' });
	window.mainLayout.observer.notify('UpdatePreferences');
	const storeActions = aras.getMainWindow().store.boundActionCreators;
	storeActions.resetPreferences(Object.keys(initialGlobalPreferences).length ? {
		Core_GlobalLayout: initialGlobalPreferences
	} : undefined);
})();
